 # the book's own words for the definition and the contrast
 Qb("ch06_transactions.adoc", "Physical cash is a bearer token.", "The data that Alice uses to convince full nodes to update their", "databases is called a _transaction_."),
 Qb("ch06_transactions.adoc", "it takes", "64 hexadecimal characters to display 32 bytes"),
 Qb("ch06_transactions.adoc", "the _extended serialization format_ is defined in BIP144", "the marker must be zero (0x00) and the flag must be", "nonzero"),
 Qb("ch06_transactions.adoc", "Legacy serialization does not include the marker, flag, and witness structure", "fields."),
 Qb("ch06_transactions.adoc", "partially signed bitcoin transaction (PSBT) format", "documented in BIPs 174 and 370"),
 Qb("ch06_transactions.adoc", "it keeps a", "database that stores every UTXO and", "essential metadata about it"),
 Qe("bip-0144.mediawiki", "The marker byte is set to zero so that this structure will never parse as a valid transaction in a parser that does not support this BIP."),
 Qe("bip-0174.mediawiki", "Partially Signed Bitcoin Transaction Format"),
 # the bytes of Alice's transaction: the book's listing, the explorer's copy and the size
 X("T.parse_tx(C.ev_hex('tx_alice_46620030_v1_0_0.hex'))['size']", 194),
