 X("[(n, p, k) for n, p, k in T.parse_tx(%r)['spans'] if n in ('version', 'marker', 'flag', 'lock time')]" % ALICE, [("version", 0, 4), ("marker", 4, 1), ("flag", 5, 1), ("lock time", 190, 4)]),
 X("(T.parse_tx(%r)['marker'], T.parse_tx(%r)['flag'], T.parse_tx(%r)['segwit'])" % (ALICE, ALICE, ALICE), (0, 1, True)),
 X("len(T.serialize(T.parse_tx(%r), witness=False))" % ALICE, 125),
 X("len(T.serialize(T.parse_tx(%r), witness=True))" % ALICE, 194),
 # a legacy transaction parses without marker and flag: the first bitcoin transaction, block 170
 X("T.parse_tx(C.ev_hex('tx_first_f4184fc5_v1_0_0.hex'))['segwit']", False),
 X("bytes.fromhex('70736274ff')[:4]", b"psbt"),
 ("len('')", "388"),
 ("(4 + 1 + 1 + 42 + 75 + 67 + 4, 4 + 1 + 1 + 1 + 4, 75 + 65)", "(194, 11, 140)"),
